export const SF_STATION_REGIONS = ["香港島", "九龍", "新界"];

export function searchSFStations(query: string, region?: string): SFStation[] {
  const q = query.toLowerCase().trim();
  if (!q && !region) return SF_STATIONS.slice(0, 20);
  return SF_STATIONS.filter(s => {
    const matchRegion = !region || s.region === region;
    const matchQuery = !q || s.code.toLowerCase().includes(q) || s.district.includes(q) || s.address.includes(q) || s.name.includes(q);
    return matchRegion && matchQuery;
  }).slice(0, 30);
}
// Unified SF point type (station or locker)
export interface SFPoint {
  code: string;
  name: string;
  district: string;
  address: string;
  region: string;
  type: 'station' | 'locker';
}

// Lazy-load lockers to avoid bundling all data upfront
let _lockers: SFPoint[] | null = null;
async function getLockers(): Promise<SFPoint[]> {
  if (_lockers) return _lockers;
  const mod = await import('./sfLockers');
  _lockers = mod.SF_LOCKERS.map(l => ({ ...l, type: 'locker' as const }));
  return _lockers;
}

// Synchronous search for stations only (used in existing code)
export function searchSFPoints(query: string, region?: string, type?: 'station' | 'locker' | 'all'): SFPoint[] {
  const q = query.toLowerCase().trim();
  const stations: SFPoint[] = SF_STATIONS.map(s => ({ ...s, type: 'station' as const }));
  if (type === 'locker') return [];
  if (!q && !region) return stations.slice(0, 20);
  return stations.filter(s => {
    const matchRegion = !region || s.region === region;
    const matchQuery = !q || s.code.toLowerCase().includes(q) || s.district.includes(q) || s.address.includes(q) || s.name.includes(q);
    return matchRegion && matchQuery;
  }).slice(0, 30);
}

// Async search for both stations and lockers
export async function searchSFPointsAsync(query: string, region?: string, type?: 'station' | 'locker' | 'all'): Promise<SFPoint[]> {
  const q = query.toLowerCase().trim();
  const stations: SFPoint[] = SF_STATIONS.map(s => ({ ...s, type: 'station' as const }));
  const lockers = await getLockers();

  let pool: SFPoint[] = [];
  if (!type || type === 'all') pool = [...stations, ...lockers];
  else if (type === 'station') pool = stations;
  else pool = lockers;

  if (!q && !region) return pool.slice(0, 20);
  return pool.filter(s => {
    const matchRegion = !region || s.region === region;
    const matchQuery = !q || s.code.toLowerCase().includes(q) || s.district.includes(q) || s.address.includes(q) || s.name.includes(q);
    return matchRegion && matchQuery;
  }).slice(0, 40);
}

// SF Express station/locker code format validation
// Station format: 852XXX (e.g., 852FTL, 852Z351)
// Locker format: H852XXXXP (e.g., H852001P, H852123P)
export function validateSFCode(code: string): { valid: boolean; type: 'station' | 'locker' | null; message?: string } {
  const trimmed = code.trim().toUpperCase();
  if (!trimmed) return { valid: false, type: null, message: "請輸入順豐站/智能櫃編號" };
  // Locker: starts with H, contains 852, ends with P
  if (trimmed.startsWith('H')) {
    // H852XXXXP format: H + 852 + 3-8 alphanumeric chars + P (e.g. H852G006P, H852FE95P)
    if (/^H852[A-Z0-9]{3,8}P$/.test(trimmed)) {
      return { valid: true, type: 'locker' };
    }
    return { valid: false, type: 'locker', message: `智能櫃編號格式不正確（應為 H852XXXXP，例：H852G006P）` };
  }
  // Station: starts with 852, followed by 2-5 alphanumeric characters
  if (trimmed.startsWith('852')) {
    if (/^852[A-Z0-9]{2,5}$/.test(trimmed)) {
      return { valid: true, type: 'station' };
    }
    return { valid: false, type: 'station', message: `順豐站編號格式不正確（應為 852XXX，例：852FTL）` };
  }
  return { valid: false, type: null, message: `無效的順豐站點編號（應以 852 或 H852 開頭）` };
}
